package com.example.hiringsys.service; import com.example.hiringsys.entity.Usuario; import com.example.hiringsys.exception.ResourceNotFoundException; import com.example.hiringsys.repository.UsuarioRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class UsuarioService { private final UsuarioRepository repository; public UsuarioService(UsuarioRepository r){repository=r;} @Transactional(readOnly=true) public Usuario buscarPorEmail(String email){return repository.findByEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("Usuário não encontrado: "+email));} }
